import { Link } from "react-router-dom";
import { useState } from "react";
import LocationSelector from "../components/LocationSelector";

const API_URL =
  import.meta.env.VITE_API_URL ||
  "https://queueless-india-a2ju.onrender.com/api";

// ======================================================
// GOVERNMENT SERVICES
// ======================================================

const purposes = [
  "Income Certificate",
  "Community Certificate",
  "Birth Certificate",
  "Driving Licence",
  "Vehicle Registration",
  "Land Records",
];

// ======================================================
// SAMPLE OFFICER DATA
// Used when backend does not return officers
// ======================================================

const SAMPLE_OFFICERS = {
  "Coimbatore RTO Office": [
    {
      _id: "sample-officer-001",
      name: "Officer Kumar",
      designation: "RTO Officer",
      services: [
        "Driving Licence",
        "Vehicle Registration",
        "Learner Licence",
      ],
      counter: "Counter 1",
      available: true,
      peopleWaiting: 4,
      estimatedWaitingTime: 16,
      expectedArrival: null,
      isSample: true,
    },

    {
      _id: "sample-officer-002",
      name: "Officer Priya",
      designation: "Senior RTO Officer",
      services: [
        "Driving Licence",
        "Vehicle Registration",
      ],
      counter: "Counter 2",
      available: true,
      peopleWaiting: 2,
      estimatedWaitingTime: 8,
      expectedArrival: null,
      isSample: true,
    },

    {
      _id: "sample-officer-003",
      name: "Officer Arun",
      designation: "RTO Assistant",
      services: [
        "Learner Licence",
        "Vehicle Registration",
      ],
      counter: "Counter 3",
      available: false,
      peopleWaiting: 7,
      estimatedWaitingTime: 28,
      expectedArrival: "2:30 PM",
      isSample: true,
    },
  ],

  "Coimbatore Taluk Office": [
    {
      _id: "sample-officer-004",
      name: "Officer Divya",
      designation: "Taluk Officer",
      services: [
        "Income Certificate",
        "Community Certificate",
        "Birth Certificate",
      ],
      counter: "Counter 1",
      available: true,
      peopleWaiting: 3,
      estimatedWaitingTime: 12,
      expectedArrival: null,
      isSample: true,
    },

    {
      _id: "sample-officer-005",
      name: "Officer Suresh",
      designation: "Revenue Officer",
      services: [
        "Land Records",
        "Income Certificate",
      ],
      counter: "Counter 2",
      available: true,
      peopleWaiting: 1,
      estimatedWaitingTime: 5,
      expectedArrival: null,
      isSample: true,
    },
  ],
};

// ======================================================
// SAMPLE OFFICE STATISTICS
// ======================================================

const SAMPLE_OFFICE_STATS = {
  "Coimbatore RTO Office": {
    availableOfficers: 2,
    waitingCount: 13,
  },

  "Coimbatore Taluk Office": {
    availableOfficers: 2,
    waitingCount: 4,
  },
};

// ======================================================
// COMPONENT
// ======================================================

function GovernmentOffices() {
  const [location, setLocation] = useState(null);

  const [offices, setOffices] = useState([]);

  const [selectedOffice, setSelectedOffice] = useState(null);

  const [purpose, setPurpose] =
    useState("Income Certificate");

  const [officers, setOfficers] = useState([]);

  const [selectedOfficer, setSelectedOfficer] =
    useState(null);

  const [citizenName, setCitizenName] =
    useState("");

  const [token, setToken] = useState(null);

  const [loading, setLoading] =
    useState(false);

  const [error, setError] =
    useState("");

  // ======================================================
  // LOAD GOVERNMENT OFFICES
  // ======================================================

  const loadOffices = async (selectedLocation) => {
    setLocation(selectedLocation);

    setSelectedOffice(null);
    setSelectedOfficer(null);
    setOfficers([]);
    setToken(null);
    setError("");

    try {
      setLoading(true);

      const params = new URLSearchParams();

      if (selectedLocation.method === "manual") {
        params.set(
          "state",
          selectedLocation.state
        );

        params.set(
          "district",
          selectedLocation.district
        );

        params.set(
          "village",
          selectedLocation.village
        );
      }

      const response = await fetch(
        `${API_URL}/government-offices?${params.toString()}`
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Unable to load offices"
        );
      }

      setOffices(data.offices || []);
    } catch (err) {
      setError(
        err.message ||
          "Unable to load government offices."
      );
    } finally {
      setLoading(false);
    }
  };

  // ======================================================
  // GET SAMPLE OFFICERS
  // ======================================================

  const getSampleOfficers = (office) => {
    if (!office) {
      return [];
    }

    return (
      SAMPLE_OFFICERS[office.name] || []
    );
  };

  // ======================================================
  // GET OFFICE SAMPLE STATS
  // ======================================================

  const getOfficeStats = (office) => {
    if (!office) {
      return {
        availableOfficers: 0,
        waitingCount: 0,
      };
    }

    return (
      SAMPLE_OFFICE_STATS[office.name] || {
        availableOfficers:
          office.availableOfficers || 0,

        waitingCount:
          office.waitingCount || 0,
      }
    );
  };

  // ======================================================
  // LOAD OFFICERS
  // ======================================================

  const loadOfficers = async (office) => {
    setSelectedOffice(office);

    setSelectedOfficer(null);
    setToken(null);
    setError("");

    try {
      setLoading(true);

      const response = await fetch(
        `${API_URL}/government-offices/${office._id}/officers?purpose=${encodeURIComponent(
          purpose
        )}`
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Unable to load officers"
        );
      }

      const realOfficers =
        data.officers || [];

      // ==================================================
      // IF API HAS REAL OFFICERS
      // USE THEM
      // ==================================================

      if (realOfficers.length > 0) {
        setOfficers(realOfficers);
      } else {
        // ==================================================
        // OTHERWISE USE SAMPLE DATA
        // ==================================================

        const sampleOfficers =
          getSampleOfficers(office);

        setOfficers(sampleOfficers);

        if (sampleOfficers.length > 0) {
          setError(
            "Showing sample officer data for prototype."
          );
        }
      }
    } catch (err) {
      // ==================================================
      // API FAILED
      // SHOW SAMPLE DATA
      // ==================================================

      const sampleOfficers =
        getSampleOfficers(office);

      if (sampleOfficers.length > 0) {
        setOfficers(sampleOfficers);

        setError(
          "Live officer data is unavailable. Showing sample officer data."
        );
      } else {
        setOfficers([]);

        setError(
          err.message ||
            "Unable to load officers."
        );
      }
    } finally {
      setLoading(false);
    }
  };

  // ======================================================
  // BOOK APPOINTMENT
  // ======================================================

  const bookAppointment = async () => {
    if (
      !citizenName.trim() ||
      !selectedOffice ||
      !selectedOfficer
    ) {
      setError(
        "Enter citizen name and select an officer."
      );

      return;
    }

    // ==================================================
    // SAMPLE OFFICER
    // Create DEMO token locally
    // ==================================================

    if (selectedOfficer.isSample) {
      const demoToken = {
        _id: `demo-${Date.now()}`,

        tokenNumber:
          selectedOffice.name.includes("RTO")
            ? "RTO-045"
            : "TALUK-012",

        expectedTime:
          `${selectedOfficer.estimatedWaitingTime} minutes`,

        governmentOffice: {
          name: selectedOffice.name,
        },

        officer: {
          name: selectedOfficer.name,
        },

        purpose: purpose,

        demo: true,
      };

      localStorage.setItem(
        "queueless_office_token",
        JSON.stringify(demoToken)
      );

      setToken(demoToken);

      setError("");

      return;
    }

    // ==================================================
    // REAL API APPOINTMENT
    // ==================================================

    try {
      setLoading(true);

      setError("");

      const response = await fetch(
        `${API_URL}/government-offices/tokens`,
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json",
          },

          body: JSON.stringify({
            citizenName:
              citizenName.trim(),

            officeId:
              selectedOffice._id,

            officerId:
              selectedOfficer._id,

            purpose,

            source: "online",
          }),
        }
      );

      const data =
        await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Unable to book appointment"
        );
      }

      localStorage.setItem(
        "queueless_office_token",
        JSON.stringify(data.token)
      );

      setToken(data.token);
    } catch (err) {
      setError(
        err.message ||
          "Unable to book appointment."
      );
    } finally {
      setLoading(false);
    }
  };

  // ======================================================
  // RENDER
  // ======================================================

  return (
    <main className="min-h-screen bg-slate-50 px-6 py-16">

      <div className="mx-auto max-w-5xl">

        {/* ==================================================
            BACK
        ================================================== */}

        <Link
          to="/"
          className="font-semibold text-blue-700 hover:text-blue-800"
        >
          Back to Home
        </Link>

        {/* ==================================================
            HEADER
        ================================================== */}

        <div className="mt-6">

          <p className="text-sm font-semibold uppercase tracking-wider text-blue-700">
            Government Offices
          </p>

          <h1 className="mt-2 text-3xl font-bold text-slate-900">
            Find nearby government offices
          </h1>

          <p className="mt-2 text-sm text-slate-500">
            Find available officers and book
            government services without waiting
            in long queues.
          </p>

        </div>

        {/* ==================================================
            LOCATION SELECTOR
        ================================================== */}

        <div className="mt-8">

          <LocationSelector
            onLocationSelected={
              loadOffices
            }
          />

        </div>

        {/* ==================================================
            ERROR / INFORMATION
        ================================================== */}

        {error && (
          <div
            className={`mt-6 rounded-xl p-4 text-sm font-medium ${
              error.includes("sample")
                ? "bg-blue-50 text-blue-700"
                : "bg-red-50 text-red-700"
            }`}
          >
            {error}
          </div>
        )}

        {/* ==================================================
            OFFICE LIST
        ================================================== */}

        {location && (

          <section className="mt-8">

            <div className="flex items-end justify-between">

              <div>

                <p className="text-sm font-semibold uppercase tracking-wide text-blue-700">
                  Available Locations
                </p>

                <h2 className="mt-1 text-2xl font-bold text-slate-900">
                  Government Office List
                </h2>

              </div>

              {loading && (
                <p className="text-sm text-slate-500">
                  Loading...
                </p>
              )}

            </div>

            {/* OFFICE CARDS */}

            <div className="mt-5 grid gap-4 md:grid-cols-2">

              {offices.map((office) => {

                const stats =
                  getOfficeStats(office);

                return (

                  <button
                    key={office._id}
                    type="button"
                    onClick={() =>
                      loadOfficers(office)
                    }
                    className={`rounded-2xl border bg-white p-6 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-blue-300 hover:shadow-md ${
                      selectedOffice?._id ===
                      office._id
                        ? "border-blue-500 ring-2 ring-blue-100"
                        : "border-slate-200"
                    }`}
                  >

                    <div className="flex items-start justify-between">

                      <div>

                        <h3 className="text-lg font-bold text-slate-900">
                          {office.name}
                        </h3>

                        <p className="mt-1 text-sm text-slate-500">
                          {office.type} •{" "}
                          {office.village},{" "}
                          {office.district}
                        </p>

                      </div>

                      <span className="rounded-full bg-green-50 px-3 py-1 text-xs font-semibold text-green-700">
                        LIVE
                      </span>

                    </div>

                    <div className="mt-5 grid grid-cols-2 gap-3">

                      <div className="rounded-xl bg-green-50 p-3">

                        <p className="text-xs text-green-700">
                          Officers
                        </p>

                        <p className="mt-1 text-lg font-bold text-green-800">
                          {
                            stats.availableOfficers
                          }
                        </p>

                        <p className="text-xs text-green-700">
                          available
                        </p>

                      </div>

                      <div className="rounded-xl bg-slate-50 p-3">

                        <p className="text-xs text-slate-500">
                          Queue
                        </p>

                        <p className="mt-1 text-lg font-bold text-slate-900">
                          {
                            stats.waitingCount
                          }
                        </p>

                        <p className="text-xs text-slate-500">
                          people waiting
                        </p>

                      </div>

                    </div>

                    <div className="mt-4 text-sm font-semibold text-blue-700">
                      View officers →
                    </div>

                  </button>

                );
              })}

            </div>

            {/* NO OFFICES */}

            {!loading &&
              offices.length === 0 && (
                <div className="mt-5 rounded-2xl border border-slate-200 bg-white p-8 text-center">

                  <p className="text-lg font-bold text-slate-900">
                    No government offices found
                  </p>

                  <p className="mt-2 text-sm text-slate-500">
                    Try selecting another location.
                  </p>

                </div>
              )}

          </section>

        )}

        {/* ==================================================
            SELECT SERVICE
        ================================================== */}

        {selectedOffice && (

          <section className="mt-8 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">

            <div>

              <p className="text-sm font-semibold uppercase tracking-wide text-blue-700">
                Step 2
              </p>

              <h2 className="mt-1 text-2xl font-bold text-slate-900">
                Select Purpose / Service
              </h2>

              <p className="mt-1 text-sm text-slate-500">
                Choose the service you need.
              </p>

            </div>

            <div className="mt-5 flex flex-wrap gap-2">

              {purposes.map((item) => (

                <button
                  key={item}
                  type="button"
                  onClick={() => {
                    setPurpose(item);
                    setSelectedOfficer(null);
                    setOfficers([]);
                    setError("");
                  }}
                  className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                    purpose === item
                      ? "bg-blue-700 text-white shadow-sm"
                      : "bg-slate-100 text-slate-700 hover:bg-slate-200"
                  }`}
                >
                  {item}
                </button>

              ))}

            </div>

            <button
              type="button"
              onClick={() =>
                loadOfficers(selectedOffice)
              }
              disabled={loading}
              className="mt-6 rounded-xl bg-slate-900 px-6 py-3 font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading
                ? "Finding Officers..."
                : "Find Officers"}
            </button>

          </section>

        )}

        {/* ==================================================
            OFFICERS
        ================================================== */}

        {selectedOffice &&
          officers.length > 0 && (

            <section className="mt-8">

              <div className="flex items-end justify-between">

                <div>

                  <p className="text-sm font-semibold uppercase tracking-wide text-blue-700">
                    Step 3
                  </p>

                  <h2 className="mt-1 text-2xl font-bold text-slate-900">
                    Available Officers
                  </h2>

                  <p className="mt-1 text-sm text-slate-500">
                    Officers at{" "}
                    {selectedOffice.name}
                  </p>

                </div>

                <div className="rounded-full bg-green-50 px-4 py-2 text-sm font-semibold text-green-700">

                  {
                    officers.filter(
                      (officer) =>
                        officer.available
                    ).length
                  }{" "}
                  Available

                </div>

              </div>

              {/* OFFICER CARDS */}

              <div className="mt-5 grid gap-5 md:grid-cols-2">

                {officers.map((officer) => (

                  <button
                    key={officer._id}
                    type="button"
                    onClick={() =>
                      setSelectedOfficer(
                        officer
                      )
                    }
                    className={`rounded-3xl border bg-white p-6 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md ${
                      selectedOfficer?._id ===
                      officer._id
                        ? "border-blue-500 ring-2 ring-blue-100"
                        : "border-slate-200"
                    }`}
                  >

                    {/* OFFICER HEADER */}

                    <div className="flex items-start justify-between">

                      <div className="flex items-center gap-4">

                        {/* AVATAR */}

                        <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-blue-100 text-xl font-bold text-blue-700">

                          {officer.name
                            ?.charAt(0)
                            ?.toUpperCase()}

                        </div>

                        <div>

                          <h3 className="text-lg font-bold text-slate-900">
                            {officer.name}
                          </h3>

                          <p className="text-sm text-slate-500">
                            {
                              officer.designation ||
                              "Government Officer"
                            }
                          </p>

                        </div>

                      </div>

                      {/* STATUS */}

                      <span
                        className={`rounded-full px-3 py-1 text-xs font-bold ${
                          officer.available
                            ? "bg-green-50 text-green-700"
                            : "bg-orange-50 text-orange-700"
                        }`}
                      >
                        {officer.available
                          ? "AVAILABLE"
                          : "BUSY"}
                      </span>

                    </div>

                    {/* SAMPLE BADGE */}

                    {officer.isSample && (
                      <div className="mt-4">

                        <span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700">
                          Demo Officer
                        </span>

                      </div>
                    )}

                    {/* OFFICER INFO */}

                    <div className="mt-5 grid grid-cols-2 gap-3">

                      <div className="rounded-xl bg-slate-50 p-3">

                        <p className="text-xs text-slate-500">
                          Counter
                        </p>

                        <p className="mt-1 font-bold text-slate-900">
                          {
                            officer.counter ||
                            "Assigned"
                          }
                        </p>

                      </div>

                      <div className="rounded-xl bg-slate-50 p-3">

                        <p className="text-xs text-slate-500">
                          People Waiting
                        </p>

                        <p className="mt-1 font-bold text-slate-900">
                          {
                            officer.peopleWaiting ??
                            0
                          }
                        </p>

                      </div>

                    </div>

                    {/* WAIT TIME */}

                    {officer.available ? (

                      <div className="mt-4 rounded-xl bg-green-50 p-4">

                        <p className="text-xs font-semibold text-green-700">
                          Estimated Waiting Time
                        </p>

                        <p className="mt-1 text-xl font-bold text-green-800">
                          {
                            officer.estimatedWaitingTime ??
                            0
                          }{" "}
                          minutes
                        </p>

                      </div>

                    ) : (

                      <div className="mt-4 rounded-xl bg-orange-50 p-4">

                        <p className="text-xs font-semibold text-orange-700">
                          Expected Arrival
                        </p>

                        <p className="mt-1 font-bold text-orange-800">
                          {
                            officer.expectedArrival ||
                            "Not updated"
                          }
                        </p>

                      </div>

                    )}

                    {/* SERVICES */}

                    {officer.services &&
                      officer.services.length >
                        0 && (

                        <div className="mt-5">

                          <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-400">
                            Services
                          </p>

                          <div className="flex flex-wrap gap-2">

                            {officer.services.map(
                              (service) => (

                                <span
                                  key={service}
                                  className="rounded-full bg-slate-100 px-3 py-1 text-xs font-medium text-slate-700"
                                >
                                  {service}
                                </span>

                              )
                            )}

                          </div>

                        </div>

                      )}

                    {/* SELECT */}

                    <div
                      className={`mt-5 text-sm font-semibold ${
                        officer.available
                          ? "text-blue-700"
                          : "text-slate-400"
                      }`}
                    >
                      {officer.available
                        ? "Select Officer →"
                        : "Officer currently busy"}
                    </div>

                  </button>

                ))}

              </div>

            </section>

          )}

        {/* ==================================================
            BOOK APPOINTMENT
        ================================================== */}

        {selectedOfficer && (

          <section className="mt-8 rounded-3xl border border-blue-100 bg-white p-6 shadow-sm">

            <p className="text-sm font-semibold uppercase tracking-wide text-blue-700">
              Step 4
            </p>

            <h2 className="mt-1 text-2xl font-bold text-slate-900">
              Book Appointment
            </h2>

            <div className="mt-5 rounded-2xl bg-slate-50 p-5">

              <div className="grid gap-4 md:grid-cols-3">

                <Info
                  label="Office"
                  value={
                    selectedOffice.name
                  }
                />

                <Info
                  label="Officer"
                  value={
                    selectedOfficer.name
                  }
                />

                <Info
                  label="Service"
                  value={purpose}
                />

              </div>

            </div>

            <input
              value={citizenName}
              onChange={(event) =>
                setCitizenName(
                  event.target.value
                )
              }
              placeholder="Enter citizen name"
              className="mt-5 w-full rounded-xl border border-slate-300 px-4 py-3 outline-none transition focus:border-blue-600 focus:ring-1 focus:ring-blue-100"
            />

            <button
              type="button"
              onClick={bookAppointment}
              disabled={
                !selectedOfficer.available ||
                loading ||
                !citizenName.trim()
              }
              className="mt-4 rounded-xl bg-blue-700 px-6 py-3 font-semibold text-white transition hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading
                ? "Booking..."
                : selectedOfficer.isSample
                ? "Create Demo Appointment"
                : "Book Appointment"}
            </button>

          </section>

        )}

        {/* ==================================================
            APPOINTMENT RESULT
        ================================================== */}

        {token && (

          <section className="mt-8 rounded-3xl border border-green-200 bg-green-50 p-6">

            <div className="flex items-start justify-between">

              <div>

                <p className="text-sm font-semibold uppercase tracking-wide text-green-700">
                  Appointment Confirmed
                </p>

                <h2 className="mt-1 text-2xl font-bold text-green-900">
                  Your Token is Ready
                </h2>

              </div>

              {token.demo && (
                <span className="rounded-full bg-blue-100 px-3 py-1 text-xs font-bold text-blue-700">
                  DEMO
                </span>
              )}

            </div>

            <div className="mt-5 grid gap-4 md:grid-cols-2">

              <Info
                label="Office"
                value={
                  token
                    .governmentOffice
                    ?.name
                }
              />

              <Info
                label="Officer"
                value={
                  token.officer?.name
                }
              />

              <Info
                label="Token"
                value={
                  token.tokenNumber
                }
              />

              <Info
                label="Expected Time"
                value={
                  token.expectedTime
                }
              />

              <Info
                label="Purpose"
                value={purpose}
              />

              <Info
                label="Counter"
                value={
                  selectedOfficer?.counter ||
                  "Assigned when called"
                }
              />

            </div>

            {token.demo ? (

              <div className="mt-5 rounded-xl bg-blue-50 p-4 text-sm text-blue-700">

                This is a prototype appointment.
                The token was generated using
                sample officer data.

              </div>

            ) : null}

            <Link
              to={`/office-queue/${token._id}`}
              className="mt-5 inline-block rounded-xl bg-blue-700 px-5 py-3 font-semibold text-white transition hover:bg-blue-800"
            >
              Track Live Queue
            </Link>

          </section>

        )}

      </div>

    </main>
  );
}

// ======================================================
// INFO COMPONENT
// ======================================================

function Info({ label, value }) {
  return (
    <div className="rounded-xl bg-white p-4">

      <p className="text-xs font-semibold uppercase tracking-wide text-slate-400">
        {label}
      </p>

      <p className="mt-1 font-bold text-slate-900">
        {value || "Not available"}
      </p>

    </div>
  );
}

export default GovernmentOffices;
